import{_ as t,a as n}from"./chunks/dataflow-converter-dialog.CaG_3Yb6.js";import{_ as s,o as r,c as o,a3 as i}from"./chunks/framework.BlfGB29P.js";const f=JSON.parse('{"title":"Flux de données – Valeurs, conversion et calcul","description":"","frontmatter":{"title":"Flux de données – Valeurs, conversion et calcul"},"headers":[],"relativePath":"fr/projects/grafik-visual-studio/datenfluss.md","filePath":"fr/projects/grafik-visual-studio/datenfluss.md","lastUpdated":1793198184000}'),a={name:"fr/projects/grafik-visual-studio/datenfluss.md"};function u(d,e,l,c,p,m){return r(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="ha-grafik-–-datenfluss" tabindex="-1">HA Grafik – Flux de données <a class="header-anchor" href="#ha-grafik-–-datenfluss" aria-label="Permalink to &quot;HA Grafik – Flux de données {#ha-grafik-–-datenfluss}&quot;">​</a></h1><p>À partir de la version <strong>0.1.287</strong>, il est possible de masquer <strong>tous les widgets</strong> via l&#39;option <strong>WIDGET → Masquer à l&#39;exécution (In Runtime verstecken)</strong>. Enregistrez le projet après avoir effectué cette opération. Un widget de type « Number » (nombre) masqué peut continuer à transmettre des valeurs à un module de calcul (« Math ») ; une « MathBox » masquée continue également d&#39;effectuer ses calculs. Cette option ne désactive pas la source des données et fonctionne indépendamment de l&#39;index Z (Z-index). Dans l&#39;éditeur, tous les éléments restent modifiables.</p><p>À partir de la version <strong>0.1.285</strong> : les éléments « SVG-Line » et « Wert-Verbindung » (connexion de valeurs) prennent en charge le paramètre <strong>Ligne → Position de départ verticale</strong>. Les lignes verticales à angle droit se tracent d&#39;abord verticalement, puis s&#39;orientent vers la gauche ou la droite pour atteindre la hauteur cible. Les poignées de contrôle apparaissent après un déplacement de 6 px ; elles ne permettent pas de déplacer une sélection multiple. Pour déplacer des lignes ancrées dans leur intégralité, utilisez la touche <strong>Alt</strong>. Une ligne SVG standard avec un <strong>index Z (Z-index) de -100 ou moins</strong> reste également invisible lors de l&#39;exécution, sans pour autant perdre ses valeurs. Elle peut servir à relier un widget « Number » à un module « Math » ; consultez les instructions et l&#39;exemple de valeur nulle sous <a href="/fr/projects/grafik-visual-studio/svg-linebox-math">LineBox Math</a>.</p><p>À partir de la version <strong>0.1.141</strong>, la palette dédiée <strong>HA Grafik – Flux de données</strong> propose trois widgets. Tous les calculs et conversions sont effectués dans le navigateur de l&#39;appareil d&#39;affichage utilisé. Home Assistant fournit les valeurs des entités ; aucune entité HA supplémentaire n&#39;est requise pour le traitement interne. La visualisation doit être ouverte pour cela.</p><table tabindex="0"><thead><tr><th>Widget</th><th>Dans l&#39;éditeur</th><th>En exécution (Runtime)</th></tr></thead><tbody><tr><td><strong>Liaison de valeur</strong></td><td>Ligne SVG simple sans animation, orientée du départ vers l&#39;arrivée</td><td>Invisible ; les valeurs sont transmises</td></tr><tr><td><strong>Convertisseur de valeur</strong></td><td>Widget et boîte de dialogue dédiée avec boutons radio, type d&#39;entrée/sortie et aperçu</td><td>Toujours invisible ; la conversion reste active</td></tr><tr><td><strong>Calcul de valeur</strong></td><td>Éditeur identique à celui de <a href="/fr/projects/grafik-visual-studio/svg-linebox-math">SVG LineBox Math</a>, avec quatre calculs et des connecteurs A–P</td><td>Invisible par défaut ; tous les calculs et sorties restent actifs</td></tr></tbody></table><p>La « Liaison de valeur » et le « Calcul de valeur » utilisent en interne les types existants <em>SVG Line</em> et <em>SVG LineBox Math</em>. Cela permet de conserver les fonctionnalités d&#39;ancrage, de déplacement, de copie, d&#39;import/export de projet, ainsi que la logique de calcul commune. Pour <em>SVG LineBox Math</em>, l&#39;option <strong>Masquer en exécution</strong> peut également être activée. Dans le cas du « Calcul de valeur », vous pouvez désactiver cette option si vous souhaitez rendre le widget de calcul visible.</p><h2 id="eine-quelle-verbinden" tabindex="-1">Connecter une source <a class="header-anchor" href="#eine-quelle-verbinden" aria-label="Permalink to &quot;Connecter une source {#eine-quelle-verbinden}&quot;">​</a></h2><p><img src="'+t+'" alt="Point de départ unique avec sélection de position"></p><p>Depuis la version 0.1.154, la section CSS « Général » reste obligatoirement active, même pour ces widgets ; les autres sections CSS sont facultatives.</p><p>À partir de la version <strong>0.1.143</strong>, les sections CSS facultatives sont désactivées par défaut pour les nouveaux widgets de flux de données ; pour les widgets de calcul de valeur, la section « Affichage » est également désactivée par défaut. Les fonctions de calcul et de conversion restent actives. Ces sections peuvent être activées si nécessaire ; les champs CSS désactivés ne sont pas exportés. Les nouvelles connexions de valeurs ne comportent pas de pointes de flèche aux extrémités. Les widgets déjà enregistrés conservent leurs paramètres actuels.</p><ol><li>Pour un widget doté d&#39;une valeur d&#39;entité ou d&#39;une valeur de prévisualisation, activez l&#39;option <strong>Activer le point de départ</strong> dans la section <strong>Flux de données</strong>. Utilisez les boutons radio (<strong>Haut</strong>, <strong>Bas</strong>, <strong>Droite</strong> ou <strong>Gauche</strong>) pour définir le point de départ au milieu du côté correspondant ; par défaut, il est situé à droite. Ce point de départ unique fonctionne indépendamment de la section <strong>Points d&#39;ancrage</strong> et peut être désactivé. Vous pouvez définir sa couleur spécifique via <strong>Paramètres → Point de départ</strong>. Ce point n&#39;est visible que dans l&#39;éditeur ; la transmission de la valeur reste active lors de l&#39;exécution (runtime). Les widgets ne disposant pas de valeur (par exemple, les simples cadres) ne transmettent aucune valeur. Les configurations existantes des points d&#39;ancrage sont conservées ; les éléments <em>LineBox</em>, <em>LineBox Math</em> et les convertisseurs continuent d&#39;utiliser leurs propres points de connexion.</li><li>Ajoutez une <strong>connexion de valeur</strong> : reliez le point de départ (source) à l&#39;entrée du convertisseur ou du récepteur. Le flux de données suit toujours cette direction, même en l&#39;absence de pointes de flèche visibles ; l&#39;animation des lignes est désactivée.</li><li>Dans le convertisseur, ouvrez <strong>Modifier la conversion</strong>, sélectionnez l&#39;entrée et la sortie, puis activez l&#39;option <strong>Activer les points d&#39;ancrage d&#39;entrée/sortie sélectionnés</strong>. Les nouveaux points d&#39;ancrage restent inactifs tant qu&#39;ils ne sont pas explicitement activés. 4. Sélectionnez la conversion et vérifiez l&#39;aperçu. Pour les éléments <strong>Number</strong> (Nombre) et <strong>String</strong> (Chaîne) du jeu de base, activez l&#39;option <strong>Activer le point d&#39;entrée</strong> sous la rubrique <strong>Flux de données</strong>. Pour les autres récepteurs standards, activez l&#39;option <strong>Reprendre la valeur du flux de données</strong> ainsi que leur point d&#39;ancrage d&#39;entrée. Dans le cas de <strong>Number</strong>, il est également possible d&#39;utiliser le mécanisme existant de reprise sur point d&#39;ancrage numérique ; ce dernier permet de continuer à additionner plusieurs valeurs numériques.</li></ol><p>Un convertisseur et le mécanisme général de reprise du flux de données autorisent <strong>exactement une source par entrée</strong>. Plusieurs connexions sortantes peuvent distribuer un même résultat vers différents récepteurs. Le convertisseur n&#39;effectue pas d&#39;addition de textes ou d&#39;états de commutation. Le composant « LineBox Math » conserve son propre mécanisme d&#39;addition pour les entrées numériques multiples.</p><h3 id="eingangspunkt-bei-number-und-string" tabindex="-1">Point d&#39;entrée pour Number et String <a class="header-anchor" href="#eingangspunkt-bei-number-und-string" aria-label="Permalink to &quot;Point d&#39;entrée pour Number et String {#eingangspunkt-bei-number-und-string}&quot;">​</a></h3><p>À partir de la version <strong>0.1.274</strong>, les deux widgets de base disposent, dans la section <strong>Flux de données</strong>, d&#39;un point d&#39;entrée dédié. Tout comme pour la sortie, vous pouvez choisir entre <strong>Haut</strong>, <strong>Bas</strong>, <strong>Droite</strong> ou <strong>Gauche</strong> ; par défaut, l&#39;entrée est située à gauche. Cette entrée fonctionne indépendamment de la zone des <strong>points d&#39;ancrage</strong>. Une fois activé, le widget récupère la valeur de la source connectée, aussi bien dans l&#39;éditeur qu&#39;en phase d&#39;exécution (<em>runtime</em>). Lors d&#39;un changement de page, les connexions d&#39;entrée existantes sont conservées. Si une sortie est également activée, la valeur reçue peut être transmise vers un autre élément.</p><p>Lorsque la réception du flux de données est désactivée, le widget affiche à nouveau sa valeur d&#39;entité ou sa valeur de prévisualisation. Les points de flux de données ne sont visibles que dans l&#39;éditeur.</p><h2 id="konverterdialog" tabindex="-1">Boîte de dialogue du convertisseur <a class="header-anchor" href="#konverterdialog" aria-label="Permalink to &quot;Boîte de dialogue du convertisseur {#konverterdialog}&quot;">​</a></h2><p><img src="'+n+'" alt="Boîte de dialogue du convertisseur avec boutons radio et prévisualisation pour la conversion d&#39;un texte de température en nombre"></p><table tabindex="0"><thead><tr><th>Conversion</th><th>Paramètres et résultat</th></tr></thead><tbody><tr><td>Nombre → Texte</td><td>0 à 10 décimales, point ou virgule décimale, unité optionnelle</td></tr><tr><td>Texte → Nombre</td><td>Détection du point/virgule décimale et de l&#39;unité associée ; sortie sous forme de nombre</td></tr><tr><td>État de commutation → Nombre</td><td>Marche → 1, Arrêt → 0 ; inversion possible</td></tr><tr><td>Nombre → État de commutation</td><td>Marche si valeur ≥ seuil, sinon Arrêt ; inversion possible</td></tr><tr><td>État de commutation → Texte</td><td>Textes personnalisés pour « Marche » et « Arrêt » ; inversion possible</td></tr><tr><td>Normalisation de l&#39;état de commutation</td><td>Lecture de <code>on/off</code>, <code>true/false</code> ou <code>1/0</code> ; sortie sous forme de booléens réels, de nombres ou de texte <code>on/off</code></td></tr><tr><td>Mise à l&#39;échelle d&#39;un nombre</td><td><code>Wert * Faktor + Offset</code>, unité cible facultative ; par ex. °C → °F avec un facteur de 1,8 et un décalage (offset) de 32</td></tr></tbody></table><p>La casse (majuscules/minuscules) et les espaces aux extrémités sont tolérés pour les états de commutation. Les états inconnus sont signalés. Seuls les paramètres correspondant au mode sélectionné sont affichés. Les modifications ne sont prises en compte qu&#39;après avoir cliqué sur <strong>Appliquer</strong> ; il est possible d&#39;annuler les changements.</p><h2 id="einheiten-und-fehler" tabindex="-1">Unités et erreurs <a class="header-anchor" href="#einheiten-und-fehler" aria-label="Permalink to &quot;Unités et erreurs {#einheiten-und-fehler}&quot;">​</a></h2><p><code>23,5 °C</code> est dissocié en une valeur numérique, <strong>23,5</strong>, et une unité, <strong>°C</strong>. S&#39;il ne s&#39;agit que d&#39;une valeur, l&#39;unité HA (Home Assistant) définie dans <code>unit_of_measurement</code> — ou, à défaut, l&#39;unité du widget — est utilisée. Si aucune de ces deux options n&#39;est disponible, vous pouvez définir une unité de secours (fallback). Si une unité est déjà présente dans le texte, elle est prioritaire et n&#39;est pas ajoutée une seconde fois lors de l&#39;affichage. L&#39;option <strong>Inclure l&#39;unité dans le texte</strong> est facultative. La simple détection d&#39;une unité n&#39;entraîne aucune conversion ; pour effectuer une conversion, vous devez sélectionner explicitement <strong>Mettre à l&#39;échelle la valeur</strong> (ou « Mise à l&#39;échelle du nombre ») en précisant le facteur, le décalage (offset) et l&#39;unité cible appropriés.</p><p>Les valeurs vides, <code>unknown</code>, <code>unavailable</code>, les nombres invalides, les états de commutation inconnus, les entrées inactives, les sources multiples et les rétroactions génèrent une erreur. Par défaut, aucune valeur n&#39;est alors émise. L&#39;option <strong>Activer une valeur de remplacement en cas d&#39;erreur</strong> est désactivée par défaut ; si elle est activée, elle renvoie le texte de remplacement saisi. Il ne s&#39;agit pas d&#39;une conversion automatique en nombre ou en booléen.</p><p>Exemple : Affichage de température <code>23,5 °C</code> → Convertisseur <strong>Texte → Nombre</strong> → Calcul de valeur <code>A * 2</code> → Nombre <strong>47,0</strong>. En mode exécution (Runtime), seuls l&#39;affichage de la température et le nombre sont visibles. Les résultats sont transmis en interne et ne sont pas automatiquement enregistrés dans Home Assistant. Un seuil simple ne dispose actuellement pas d&#39;hystérésis ; le changement s&#39;opère directement au niveau de la limite.</p>',23)])])}const h=s(a,[["render",u]]);export{f as __pageData,h as default};
